# presets_meta.py에 추가할 앵커 및 키 목록
# ═══════════════════════════════════════════════════
ANCHOR_KEY = '"deepblack_trio_rivera_aztec_klimt_voidbl",'
NEW_META_KEYS = list(NEW_PRESETS.keys())


def patch_json():
    """deepblack_trio.json에 프롬프트 추가"""
    shutil.copy(JSON_PATH, str(JSON_PATH) + ".bak")
    with open(JSON_PATH, encoding="utf-8-sig") as f:
        data = json.load(f)

    added, skipped = [], []
    for key, val in NEW_PRESETS.items():
        if key in data:
            skipped.append(key)
        else:
            data[key] = val
            added.append(key)

    with open(JSON_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    print(f"✅ JSON 패치: 추가 {len(added)}종 / 스킵 {len(skipped)}종")
    return added


def patch_meta():
    """presets_meta.py DeepBlack 카테고리에 키 추가"""
    shutil.copy(META_PATH, str(META_PATH) + ".bak")
    with open(META_PATH, encoding="utf-8-sig") as f:
        meta = f.read()

    # DeepBlack 카테고리가 없으면 마지막 } 앞에 새 카테고리 추가
    if '"🖤 DeepBlack Trio"' not in meta:
        keys_str = "\n".join(f'        "{k}",' for k in NEW_META_KEYS)
        new_category = f'\n    "🖤 DeepBlack Trio": [\n{keys_str}\n    ],\n'
        # PRESET_CATEGORIES 딕셔너리 마지막 } 앞에 삽입
        last_brace = meta.rfind("\n}")
        meta = meta[:last_brace] + new_category + meta[last_brace:]
        print(f"✅ presets_meta.py: 새 카테고리 '🖤 DeepBlack Trio' 생성 + {len(NEW_META_KEYS)}종 추가")
    else:
        # 기존 카테고리에 앵커 뒤에 추가
        added = []
        for key in NEW_META_KEYS:
            if f'"{key}"' in meta:
                continue
            # 카테고리 끝 ] 앞에 추가
            insert = f'        "{key}",\n'
            target = '"🖤 DeepBlack Trio": ['
            idx = meta.find(target)
            if idx == -1:
                continue
            end_bracket = meta.find(']', idx)
            meta = meta[:end_bracket] + insert + meta[end_bracket:]
            added.append(key)
        print(f"✅ presets_meta.py: {len(added)}종 추가")

    with open(META_PATH, "w", encoding="utf-8") as f:
        f.write(meta)


def validate_meta():
    try:
        ast.parse(META_PATH.read_text(encoding="utf-8"))
        print(f"✅ AST OK: {META_PATH.name}")
        return True
    except SyntaxError as e:
        print(f"❌ AST 오류: {META_PATH.name} → {e}")
        return False


if __name__ == "__main__":
    print("🖤 DeepBlack Crossover 51~80 JSON + META 패치 시작")
    patch_json()
    patch_meta()
    print("\n🔍 AST 검증...")
    ok = validate_meta()
    if ok:
        print("\n🎉 완료! 커밋하세요:")
        print("""
git add -A
git commit -m "feat: DeepBlack Crossover 51~80 JSON 프롬프트 + presets_meta 카테고리 추가"
git push
""")
    else:
        print("⚠️ AST 실패 — .bak 파일로 복구하세요")
